import{_ as a,o,c as s,ae as n}from"./chunks/framework.YL6nI5ZP.js";const S=JSON.parse('{"title":"Formatos de datos","description":"","frontmatter":{},"headers":[],"relativePath":"es/reference/05-formatos-de-datos.md","filePath":"es/reference/05-formatos-de-datos.md"}'),d={name:"es/reference/05-formatos-de-datos.md"};function t(r,e,c,i,p,l){return o(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="formatos-de-datos" tabindex="-1">Formatos de datos <a class="header-anchor" href="#formatos-de-datos" aria-label="Permalink to &quot;Formatos de datos&quot;">​</a></h1><p>Los cuatro formatos de datos que la app lee y escribe: el archivo de proyecto, el dialecto INP, el binario <code>.out</code> y el archivo de malla <code>.2dm</code>.</p><h2 id="archivo-de-proyecto-oswmm-json" tabindex="-1">Archivo de proyecto (<code>.oswmm.json</code>) <a class="header-anchor" href="#archivo-de-proyecto-oswmm-json" aria-label="Permalink to &quot;Archivo de proyecto (\`.oswmm.json\`)&quot;">​</a></h2><p>El JSON producido por <code>Net.serialize()</code> (<code>network.js:465-488</code>) — un snapshot completo de <code>{title, units, options, nodes, links, subcatchments, mesh2D, mesh2DIndexed, timeseries, curves, lidControls, lidUsages, pollutants, landUses, treatments, aquifers, snowpacks, snowpackAssignments, rawSections, …}</code>. Es lo que <strong>Save</strong> escribe y <strong>Load</strong> lee.</p><h2 id="dialecto-inp-swmm-estandar-extensiones-2d" tabindex="-1">Dialecto INP (SWMM estándar + extensiones 2D) <a class="header-anchor" href="#dialecto-inp-swmm-estandar-extensiones-2d" aria-label="Permalink to &quot;Dialecto INP (SWMM estándar + extensiones 2D)&quot;">​</a></h2><p>Escrito por <code>inpExporter.generateInp</code> (<code>inpExporter.js:7-715</code>) en un orden de secciones estable:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[TITLE] [OPTIONS] [EVAPORATION] [RAINGAGES] [RDII_DECAY]</span></span>
<span class="line"><span>[SUBCATCHMENTS] [SUBAREAS] [INFILTRATION]</span></span>
<span class="line"><span>[JUNCTIONS] [OUTFALLS] [STORAGE] [DIVIDERS]</span></span>
<span class="line"><span>[CONDUITS] [LOSSES] [PUMPS] [WEIRS] [ORIFICES] [OUTLETS] [XSECTIONS]</span></span>
<span class="line"><span>[TIMESERIES] [TAGS] [REPORT]</span></span>
<span class="line"><span>[COORDINATES] [VERTICES] [POLYGONS] [SYMBOLS]</span></span>
<span class="line"><span>  2D mesh sections:</span></span>
<span class="line"><span>  ;; UNITS: SI (m)</span></span>
<span class="line"><span>  ;; 2D_ORIGIN &lt;lng&gt; &lt;lat&gt;</span></span>
<span class="line"><span>  [2D_OPTIONS]</span></span>
<span class="line"><span>  [2D_VERTICES]  X Y Z TAG</span></span>
<span class="line"><span>  [2D_TRIANGLES] V1 V2 V3 MANNINGS_N TAG</span></span>
<span class="line"><span>  [2D_VERTEX_NODE_MAP]   (optional)</span></span>
<span class="line"><span>  [2D_MESH_FILE] FILE &lt;name&gt;.2dm   (external mode)</span></span>
<span class="line"><span>[CURVES] [LID_CONTROLS] [LID_USAGE] [POLLUTANTS] [LANDUSES] [BUILDUP] [WASHOFF]</span></span>
<span class="line"><span>[TREATMENT] [AQUIFERS] [GROUNDWATER] [SNOWPACKS] [SNOWPACK_ASSIGNMENT]</span></span>
<span class="line"><span>+ any unrecognized rawSections re-emitted verbatim (inpExporter.js:696-712)</span></span></code></pre></div><p>Comportamientos clave de exportación: precedencia de opciones valor de UI → <code>opt.raw</code> → default (<code>inpExporter.js:47-50</code>); heurística de <code>REPORT_STEP</code> desde el valor importado → primer intervalo de gage → 1 h (<code>:54-69</code>); desplazamiento de columna OUTFALL para tipos stage (<code>:207-215</code>); manejo de WEIR ROADWAY (<code>:287-295</code>); whitelist de <code>REPORT</code> (<code>:390-403</code>).</p><p>El parser (<code>inpParser.js:7-29</code>) es <strong>sin pérdidas</strong>: cada sección se conserva tokenizada (<code>sections</code>) <em>y</em> cruda (<code>rawSections</code>), para que todo lo que la UI no puede editar sobreviva al export.</p><h2 id="formato-binario-out-salida-de-swmm" tabindex="-1">Formato binario <code>.out</code> (salida de SWMM) <a class="header-anchor" href="#formato-binario-out-salida-de-swmm" aria-label="Permalink to &quot;Formato binario \`.out\` (salida de SWMM)&quot;">​</a></h2><p>Parseado por <code>swmmOutParser.js</code>: magic del footer <code>516114522</code>, header de versión/unidades de flujo, tablas de nombres de IDs con largo prefijado, conteos de variables por clase de objeto y registros Float32 por período para subcuencas (8 vars), nodos (6), enlaces (5) y sistema (14). Expuesto como vistas typed-array de zero-copy.</p><p>Disposición del footer: los últimos seis INT32 son <code>idNamesOffset, objPropsOffset, resultsOffset, numPeriods, errCode, magicEnd</code>; se valida el valor magic <code>516114522</code>. Caminos calientes: <code>getTimeSeries(type,index,varIndex)</code> (cacheado) y <code>getStepData(type,step,varIndex)</code> para el coloreado del mapa por paso.</p><h2 id="archivo-de-malla-2dm-modo-externo" tabindex="-1">Archivo de malla <code>.2dm</code> (modo externo) <a class="header-anchor" href="#archivo-de-malla-2dm-modo-externo" aria-label="Permalink to &quot;Archivo de malla \`.2dm\` (modo externo)&quot;">​</a></h2><p><code>Mesh2DExport.build2dmText</code> (<code>mesh2dExport.js:40</code>) emite el mismo contenido <code>2D_VERTICES</code>/<code>2D_TRIANGLES</code>/<code>2D_OPTIONS</code> como texto independiente referenciado vía <code>[2D_MESH_FILE]</code>.</p>`,14)])])}const E=a(d,[["render",t]]);export{S as __pageData,E as default};
